window.UNF_GLOSSARY=[{"term":"艾略特波浪理论","name":"","def":"艾略特波浪理论把顺势推进拆为5浪（1、3、5推进，2、4回调），把逆势修正拆为3浪（A、B、C），帮你回答“若当前符合标准波浪模型，哪个价位被破会直接证伪当前数浪假设”。","path":"learn/117-zh.html","title":"艾略特波浪理论","g":"market","isDef":1},{"term":"标普全球美国服务业 PMI","name":"","def":"标普美国服务业标题指标主要看商业活动比上月怎样变化；它不等于把所有服务业分项简单平均。","path":"info/learn/26-zh.html","title":"标普全球美国服务业 PMI","g":"info","isDef":1},{"term":"标普全球美国制造业 PMI","name":"","def":"标普全球对美国制造业企业的月度调查。","path":"info/learn/25-zh.html","title":"标普全球美国制造业 PMI","g":"info","isDef":1},{"term":"财政部一般账户余额 TGA","name":"","def":"财政部一般账户（TGA）是美国财政部设在美联储的官方现金结算账户，政府日常征收税款与发行国债募集的现金通常汇入该账户，而发放联邦福利、支付政府采购账单或偿还到期国债本息时资金则从该账户流出。","path":"info/learn/54-zh.html","title":"财政部一般账户余额 TGA","g":"info","isDef":1},{"term":"缠论","name":"","def":"缠论通过递进的几何合并规则，帮你回答“合并相邻重叠毛刺后，走势在同级别下如何围绕重叠中枢震荡或离开”。","path":"learn/122-zh.html","title":"缠论","g":"market","isDef":1},{"term":"产能利用率","name":"","def":"工业实际产出相对于可持续产能用了多少。","path":"info/learn/28-zh.html","title":"产能利用率","g":"info","isDef":1},{"term":"成屋签约销售","name":"","def":"成屋签约销售指数（Pending Home Sales Index，简称PHS）由全美房地产经纪人协会（NAR）按月发布，用来追踪美国二手住宅市场里买卖双方“已经签署购房合同、但尚未走完过户交割流程（Pending）”的交易活动变化。","path":"info/learn/45-zh.html","title":"成屋签约销售","g":"info","isDef":1},{"term":"成屋销售","name":"","def":"成屋销售（Existing-Home Sales）由全美房地产经纪人协会（NAR）按月发布，用来统计美国二手住宅在当月正式办完产权过户交割手续（Closing）的成交套数、待售库存及成交中位价。","path":"info/learn/43-zh.html","title":"成屋销售","g":"info","isDef":1},{"term":"出口物价指数","name":"","def":"跟踪美国卖到国外的商品和部分服务的美元价格。","path":"info/learn/8-zh.html","title":"出口物价指数","g":"info","isDef":1},{"term":"初请失业金人数","name":"","def":"一周内第一次提出失业保险申请的件数，是裁员压力较快的温度计，但不是全体新失业人数。","path":"info/learn/16-zh.html","title":"初请失业金人数","g":"info","isDef":1},{"term":"道氏理论","name":"","def":"道氏理论把波动划分为主要趋势（潮汐）、次级折返（波浪）和日常小波动（涟漪），并看相关指数是否相互印证，帮你回答“眼前的下跌是大趋势反转，还是上涨中途的正常回撤”。","path":"learn/116-zh.html","title":"道氏理论","g":"market","isDef":1},{"term":"抵押贷款利率","name":"","def":"房地美初级抵押贷款市场调查利率（Freddie Mac Primary Mortgage Market Survey，简称PMMS）由美国政府支持企业房地美（Freddie Mac）于每周四中午发布，用来公布美国最主流的“30年期固定利率按揭贷款（30-Year Fixed-Rate Mortgage）”及15年期固定按揭的全国平均利率水平。","path":"info/learn/49-zh.html","title":"抵押贷款利率","g":"info","isDef":1},{"term":"订单流分析","name":"","def":"订单流分析把“已撮合成交的逐笔买卖单（Tape）”与“挂在盘口等待的限价单（DOM）”拆开对照，帮你回答“关键位上的挂单是真的被吃掉了，还是在成交前撤单跑了”。","path":"learn/125-zh.html","title":"订单流分析","g":"market","isDef":1},{"term":"非农就业人数","name":"","def":"美国非农机构工资单上的岗位数量；常说的新增非农是本月比上月多了多少岗位，不是就业总人口。","path":"info/learn/11-zh.html","title":"非农就业人数","g":"info","isDef":1},{"term":"隔夜逆回购余额 ON RRP","name":"","def":"隔夜逆回购余额（Overnight Reverse Repurchase Agreements Facility，简称ON RRP）由纽约联储（Federal Reserve Bank of New York）在每个美国营业日中午操作后公布，用来统计货币市场基金（MMFs）、政府支持企业（GSEs）和银行等合资格机构，当天选择把闲置现金隔夜存放在美联储账上、以换取美联储名下国债作抵押并赚取固定逆回购利息的总金额。","path":"info/learn/53-zh.html","title":"隔夜逆回购余额 ON RRP","g":"info","isDef":1},{"term":"个人储蓄率","name":"","def":"个人储蓄率（Personal Saving Rate）由美国经济分析局（BEA）按月随《个人收入与支出》报告发布，用来衡量美国整个居民部门当期税后可支配收入（DPI）在扣除个人消费支出、非房贷利息支出和经常性转移支付之后，剩余部分占可支配收入的百分比。","path":"info/learn/36-zh.html","title":"个人储蓄率","g":"info","isDef":1},{"term":"个人收入","name":"","def":"居民获得的工资、经营收入、财产收入、转移支付等汇总，帮助判断消费有没有收入支撑，而不只靠借钱。","path":"info/learn/34-zh.html","title":"个人收入","g":"info","isDef":1},{"term":"工业产出","name":"","def":"衡量美国制造业、矿业和公用事业的实际产出，尽量剔除价格。","path":"info/learn/27-zh.html","title":"工业产出","g":"info","isDef":1},{"term":"供需区分析","name":"","def":"供需区分析把过去曾“短暂停顿后突然快速拉升或急跌”的起点K线框出来，帮你回答“历史失衡起跳台在哪个价格范围，以及首次回探时是否还有反应”。","path":"learn/127-zh.html","title":"供需区分析","g":"market","isDef":1},{"term":"国债净发行规模","name":"","def":"国债净发行规模（Net Marketable Treasury Borrowing）衡量美国财政部在特定期间内通过发行可流通国债向私人市场新筹集的资金总额，减去同期归还到期旧债本金后的净新增借款额。","path":"info/learn/62-zh.html","title":"国债净发行规模","g":"info","isDef":1},{"term":"核心 CPI","name":"","def":"从CPI中去掉食品和能源，用来观察容易被油价、菜价盖住的价格趋势。","path":"info/learn/2-zh.html","title":"核心 CPI","g":"info","isDef":1},{"term":"核心 PCE","name":"","def":"PCE物价指数剔除食品和能源后的分项，常用来观察通胀是否持续降温。","path":"info/learn/4-zh.html","title":"核心 PCE","g":"info","isDef":1},{"term":"核心 PPI","name":"","def":"这里明确采用最终需求剔除食品和能源口径。","path":"info/learn/6-zh.html","title":"核心 PPI","g":"info","isDef":1},{"term":"核心资本品订单","name":"","def":"通常指剔除飞机的非国防资本品订单，想更接近企业购买设备的意愿，减少军工和大飞机合同干扰。","path":"info/learn/30-zh.html","title":"核心资本品订单","g":"info","isDef":1},{"term":"加密 ETF 每日资金流量","name":"","def":"加密ETF每日资金流量（Crypto ETF Daily Net Flows）统计现货比特币或以太坊等交易所交易基金（ETF）在每个美股交易日内，因基金份额净申购（Net Creations）与净赎回（Net Redemptions）所对应的资金净流入或净流出金额。","path":"info/learn/64-zh.html","title":"加密 ETF 每日资金流量","g":"info","isDef":1},{"term":"价格行为（裸K）","name":"","def":"价格行为（裸K）直接通过K线波段的高低点排列、推进与回调的速度对比及关键位反应，帮你回答“市场是在上台阶、下台阶还是原地重叠拉锯”。","path":"learn/115-zh.html","title":"价格行为（裸K）","g":"market","isDef":1},{"term":"建筑许可","name":"","def":"建筑许可（Building Permits）由美国人口普查局（U.S. Census Bureau）与住房和城市发展部（HUD）按月随《新住宅建设》报告同步发布，用来统计全美实行施工许可制度的地区内，地方政府当月批准新建私人住宅的套数。","path":"info/learn/42-zh.html","title":"建筑许可","g":"info","isDef":1},{"term":"江恩理论","name":"","def":"江恩工具（如江恩角度线Gann Fan）把“价格变动”与“经过的K线根数”绑定成固定比例斜线，帮你回答“若按每1根K线对应固定价格单位（1×1）作基准速度，当前走势是快于还是慢于该速度”。","path":"learn/121-zh.html","title":"江恩理论","g":"market","isDef":1},{"term":"进口物价指数","name":"","def":"跟踪美国从国外买入商品和部分服务的价格变化，以美元计价。","path":"info/learn/7-zh.html","title":"进口物价指数","g":"info","isDef":1},{"term":"经典图表形态","name":"","def":"经典图表形态把几十根K线连成的轮廓归类为双顶底、头肩、三角形或旗形，帮你回答“多空在较长时间里怎样拉锯过渡，哪条边界被突破才算打破僵局”。","path":"learn/114-zh.html","title":"经典图表形态","g":"market","isDef":1},{"term":"居民贷款逾期率","name":"","def":"居民贷款逾期率（Household Loan Delinquency Rates）主要由美联储委员会发布，并常辅以纽约联储的《家庭债务与信贷季度报告》，用来衡量信用卡、汽车贷款、个人消费贷及住宅按揭贷款余额中未按合同期限定期还款的贷款占比。","path":"info/learn/40-zh.html","title":"居民贷款逾期率","g":"info","isDef":1},{"term":"可支配个人收入","name":"","def":"个人收入扣除个人经常税后的收入，是居民税后可用于消费或储蓄的钱；可支配不等于扣掉房租等生活费。","path":"info/learn/35-zh.html","title":"可支配个人收入","g":"info","isDef":1},{"term":"蜡烛图形态","name":"","def":"蜡烛图形态通过单根或两三根K线的开盘、最高、最低、收盘关系，帮你回答“这一时段谁掌控了收盘、盘中谁曾冲锋但被推回”。","path":"learn/113-zh.html","title":"蜡烛图形态","g":"market","isDef":1},{"term":"劳动参与率","name":"","def":"16岁及以上非机构平民人口中，正在工作或积极找工作的人占比；它看“有多少人参加劳动市场”。","path":"info/learn/13-zh.html","title":"劳动参与率","g":"info","isDef":1},{"term":"零售销售","name":"","def":"零售商及餐饮服务的销售金额，主要看居民买商品花钱情况，覆盖不了医疗、住房等大部分服务消费。","path":"info/learn/31-zh.html","title":"零售销售","g":"info","isDef":1},{"term":"零售销售控制组","name":"","def":"常用口径从零售销售剔除汽车、汽油、建材及餐饮服务，帮助观察较贴近GDP商品消费估计的一组销售。","path":"info/learn/32-zh.html","title":"零售销售控制组","g":"info","isDef":1},{"term":"美国财政预算赤字","name":"","def":"美国财政预算赤字衡量联邦政府在特定月份或财年内，总财政支出（Outlays）与总财政收入之间的收支差额：当期支出大于收入即为财政赤字（Deficit），收入大于支出则为财政盈余（Surplus）。","path":"info/learn/63-zh.html","title":"美国财政预算赤字","g":"info","isDef":1},{"term":"美国国债拍卖结果","name":"","def":"美国国债拍卖结果（U.S. Treasury Auction Results）记录美国财政部在一级市场公开招标发行新国债时的最终成交定价与认购分布情况。","path":"info/learn/61-zh.html","title":"美国国债拍卖结果","g":"info","isDef":1},{"term":"美联储利率决议","name":"","def":"美联储利率决议（Federal Reserve FOMC Rate Decision）由美国联邦公开市场委员会（FOMC）按年度日程于美东时间周三下午14:00发布政策声明，14:30举行美联储主席新闻发布会，并在3月、6月、9月、12月季末例会同步公布《经济预测摘要（SEP）》与利率点阵图（Dot Plot）。","path":"info/learn/66-zh.html","title":"美联储利率决议","g":"info","isDef":1},{"term":"美联储贴现窗口借款","name":"","def":"美联储贴现窗口借款是合资格存款类金融机构以合格贷款或证券作为抵押品，直接向美联储申请短期流动性周转的官方常设工具。","path":"info/learn/60-zh.html","title":"美联储贴现窗口借款","g":"info","isDef":1},{"term":"美联储资产负债表","name":"","def":"美联储资产负债表由美联储委员会于每周四下午发布，完整列出美联储截至本周三的“资产端”与“负债端”。","path":"info/learn/51-zh.html","title":"美联储资产负债表","g":"info","isDef":1},{"term":"美元指数 DXY","name":"","def":"美元指数（DXY）是衡量美元相对于一篮子外币强弱的温度计。","path":"info/learn/73-zh.html","title":"美元指数 DXY","g":"info","isDef":1},{"term":"美债收益率与收益率曲线","name":"","def":"美债收益率是全球风险资产定价的“地心引力”。","path":"info/learn/72-zh.html","title":"美债收益率与收益率曲线","g":"info","isDef":1},{"term":"密歇根大学通胀预期","name":"","def":"调查美国消费者觉得未来物价每年会涨多少。","path":"info/learn/10-zh.html","title":"密歇根大学通胀预期","g":"info","isDef":1},{"term":"密歇根大学消费者信心","name":"","def":"密歇根大学消费者信心指数（University of Michigan Consumer Sentiment Index）由密歇根大学社会研究所按月分“初值（Preliminary）”和“终值（Final）”两次发布，通过电话与网络问卷评估美国居民对个人财务状况、整体经济前景及大件商品购买条件的看法，并同步公布备受央行关注的1年期与5-10年期通胀预期。","path":"info/learn/38-zh.html","title":"密歇根大学消费者信心","g":"info","isDef":1},{"term":"耐用品订单","name":"","def":"美国制造商接到的预计使用三年或以上商品的新订单，如设备、汽车和飞机；反映未来生产需求的一部分。","path":"info/learn/29-zh.html","title":"耐用品订单","g":"info","isDef":1},{"term":"欧洲央行利率决议","name":"","def":"欧洲央行利率决议（ECB Monetary Policy Decision）由欧洲中央银行管理委员会（Governing Council）按日程于法兰克福时间周四下午14:15发布政策声明，14:45由欧洲央行行长举行新闻发布会，并在3月、6月、9月、12月季度会议同步公布欧元区宏观经济预测（Staff Projections）。","path":"info/learn/67-zh.html","title":"欧洲央行利率决议","g":"info","isDef":1},{"term":"拍卖市场理论","name":"","def":"拍卖市场理论把价格波动看作寻找“买卖双方都愿大量交手的价格区”的双向拍卖，帮你回答“当前价格是在旧价值区里被接受，还是已拒绝旧区、向外寻找新平衡”。","path":"learn/126-zh.html","title":"拍卖市场理论","g":"market","isDef":1},{"term":"平均每周工时","name":"","def":"私人非农员工每周平均工作几小时。","path":"info/learn/15-zh.html","title":"平均每周工时","g":"info","isDef":1},{"term":"平均时薪","name":"","def":"私人非农雇员平均每小时税前工资。","path":"info/learn/14-zh.html","title":"平均时薪","g":"info","isDef":1},{"term":"趋势线与通道","name":"","def":"趋势线与通道用斜线连接依次抬高的波段低点并配平行边线，帮你回答“近期价格沿怎样的斜率推进，当前是否冲出或跌破原有斜坡”。","path":"learn/112-zh.html","title":"趋势线与通道","g":"market","isDef":1},{"term":"日本央行利率决议","name":"","def":"日本央行利率决议（Bank of Japan Monetary Policy Decision）由日本银行（BOJ）政策委员会按日程在为期两天的会议结束后公布，下午由日本央行行长举行记者会，并在1月、4月、7月、10月季度会议同步发布《经济与物价形势展望报告（Outlook Report）》。","path":"info/learn/69-zh.html","title":"日本央行利率决议","g":"info","isDef":1},{"term":"商业银行存款","name":"","def":"商业银行存款统计美国境内商业银行资产负债表上对储户和企业承担的存款总额，是评估银行体系日常资金来源是否稳定的高频窗口。","path":"info/learn/56-zh.html","title":"商业银行存款","g":"info","isDef":1},{"term":"商业银行贷款","name":"","def":"商业银行贷款统计美国商业银行资产负债表上已经发放但尚未收回的存量贷款与融资租赁总额。","path":"info/learn/57-zh.html","title":"商业银行贷款","g":"info","isDef":1},{"term":"社会融资规模","name":"","def":"如果只看银行新增贷款，你会漏掉政府发债、企业发债和股票融资等庞大的资金渠道。","path":"info/learn/78-zh.html","title":"社会融资规模","g":"info","isDef":1},{"term":"失业率","name":"","def":"在正在工作或积极找工作的人里，没有工作、可以工作且符合找工作条件的人占多少。","path":"info/learn/12-zh.html","title":"失业率","g":"info","isDef":1},{"term":"实际个人消费支出","name":"","def":"把消费金额中的价格变化尽量去掉，观察美国居民实际消费的商品和服务数量，是判断需求的重要总账。","path":"info/learn/33-zh.html","title":"实际个人消费支出","g":"info","isDef":1},{"term":"市场结构分析","name":"","def":"市场结构分析通过标记同周期连续的波段高点（HH/LH）与低点（HL/LL），帮你回答“当前趋势阶梯是在顺延（BOS），还是最新一级台阶已被反向击穿”。","path":"learn/120-zh.html","title":"市场结构分析","g":"market","isDef":1},{"term":"威科夫方法","name":"","def":"威科夫方法把横盘区间的价格高低与成交量变化放在一起对比，帮你回答“这段箱体横盘里，是下方抛压在枯竭，还是上方买盘在力竭”。","path":"learn/118-zh.html","title":"威科夫方法","g":"market","isDef":1},{"term":"稳定币定期储备与鉴证报告","name":"","def":"稳定币定期储备与鉴证报告（Stablecoin Reserve and Attestation Reports）是由锚定法币的稳定币发行商定期披露的储备资产明细说明，以及由独立第三方会计师事务所出具的鉴证报告（Attestation Report）。","path":"info/learn/65-zh.html","title":"稳定币定期储备与鉴证报告","g":"info","isDef":1},{"term":"消费者信贷","name":"","def":"消费者信贷由美联储委员会（Federal Reserve Board）按月发布，用来衡量美国居民部门尚未偿还的、不以房地产作抵押的消费债务总额及月度变化，主要分为信用卡等“循环信贷（Revolving）”与汽车贷款、学生贷款等“非循环信贷（Nonrevolving）”。","path":"info/learn/39-zh.html","title":"消费者信贷","g":"info","isDef":1},{"term":"谐波形态","name":"","def":"谐波形态用斐波那契比例逐段核对五点四腿（X-A-B-C-D）折线的长度关系，帮你回答“当前四段波段比例是否符合某种几何模型（如Gartley），以及潜在观察区（PRZ）落在哪”。","path":"learn/119-zh.html","title":"谐波形态","g":"market","isDef":1},{"term":"新屋开工","name":"","def":"新屋开工（Housing Starts）由美国人口普查局（U.S. Census Bureau）与住房和城市发展部（HUD）按月联合发布，用来统计美国私人住宅建设项目中当月已经正式破土动工的住宅套数。","path":"info/learn/41-zh.html","title":"新屋开工","g":"info","isDef":1},{"term":"新屋销售","name":"","def":"新屋销售（New Residential Sales，常称New Home Sales）由美国人口普查局（U.S. Census Bureau）与住房和城市发展部（HUD）按月联合发布，用来统计美国新建成的私人独栋住宅（New Single-Family Houses）在当月签订购房合同或收到买方定金的套数、待售库存及售价。","path":"info/learn/44-zh.html","title":"新屋销售","g":"info","isDef":1},{"term":"信用利差","name":"","def":"信用利差是债券市场给企业违约风险定的“保费差价”。","path":"info/learn/75-zh.html","title":"信用利差","g":"info","isDef":1},{"term":"续请失业金人数","name":"","def":"已经申请过、仍继续领取或申请失业保险的人次规模，帮助看失业者能否较快找到新工作。","path":"info/learn/17-zh.html","title":"续请失业金人数","g":"info","isDef":1},{"term":"银行准备金","name":"","def":"存款机构准备金余额由美联储委员会在每周四的H.4.1报告及月度H.6报告中发布，用来统计全美商业银行及其他存款机构存放在美联储账户里的结算资金总额。","path":"info/learn/52-zh.html","title":"银行准备金","g":"info","isDef":1},{"term":"英国央行利率决议","name":"","def":"英国央行利率决议（Bank of England MPC Rate Decision）由英格兰银行货币政策委员会（Monetary Policy Committee，简称MPC）按日程于伦敦时间周四中午12:00发布，同步公布《货币政策摘要与会议纪要（Minutes）》，并在2月、5月、8月、11月季度例会一并发布包含通胀与GDP预测的《货币政策报告（MPR）》及行长记者会。","path":"info/learn/68-zh.html","title":"英国央行利率决议","g":"info","isDef":1},{"term":"支撑与阻力","name":"","def":"支撑与阻力把过去价格多次停下并折返的区域标在图上，帮你回答“历史上买卖双方常在哪一带发生明显争夺或转向”。","path":"learn/111-zh.html","title":"支撑与阻力","g":"market","isDef":1},{"term":"中国 CPI","name":"","def":"中国CPI是度量国内居民日常购买商品和服务价格水平变动的核心通胀指标。","path":"info/learn/76-zh.html","title":"中国 CPI","g":"info","isDef":1},{"term":"中国官方制造业 PMI","name":"","def":"中国官方制造业PMI是每月最早公布（月末当天就出当月数）的宏观经济“先遣哨兵”。","path":"info/learn/77-zh.html","title":"中国官方制造业 PMI","g":"info","isDef":1},{"term":"谘商会消费者信心","name":"","def":"谘商会消费者信心指数（Conference Board Consumer Confidence Index）由美国世界大型企业联合会（The Conference Board）按月发布，通过问卷调查美国居民对当前商业环境、就业岗位充裕度以及未来六个月收入与经济前景的主观评价。","path":"info/learn/37-zh.html","title":"谘商会消费者信心","g":"info","isDef":1},{"term":"A Map of the Web3 Industry","name":"行业地图","def":"按技术层级与业务职能对 Web3 行业生态进行的系统划分，涵盖底层基础设施层、中间件与工具层、应用层以及外围服务与研究生态。","path":"learn/220-zh.html","title":"A Map of the Web3 Industry 行业地图","g":"web3","isDef":1},{"term":"Accumulation/Distribution","name":"累积派发线","def":"看成交量是否经常伴随着靠上端或靠下端的收盘，并把结果累积。","path":"learn/77-zh.html","title":"Accumulation/Distribution 累积派发线","g":"market","isDef":1},{"term":"ADP","name":"私营部门就业人数","def":"用ADP薪资处理数据估算美国私人部门就业变化。","path":"info/learn/20-zh.html","title":"ADP 私营部门就业人数","g":"info","isDef":1},{"term":"ADR","name":"平均每日振幅","def":"ADR算过去若干天各自最高减最低，再求平均，描述‘一天内部通常走开多大距离’。","path":"learn/29-zh.html","title":"ADR 平均每日振幅","g":"market","isDef":1},{"term":"Advance/Decline","name":"腾落线","def":"腾落线看的是一群股票有没有广泛参与涨跌，不是单只股票的K线。","path":"learn/104-zh.html","title":"Advance/Decline 腾落线","g":"market","isDef":1},{"term":"ADX","name":"趋势强度","def":"先回答行情有没有持续往一边走，再决定是否值得继续研究趋势。","path":"learn/41-zh.html","title":"ADX 趋势强度","g":"market","isDef":1},{"term":"Aggregators & Launchpads","name":"聚合器与代币首发平台","def":"交易聚合器是通过智能路由算法在多个去中心化交易所间拆分订单以降低滑点与成本的入口工具；代币首发平台（Launchpad / IDO）则是协助新项目在链上进行早期代币公开发售与募集资金的平台。","path":"learn/226-zh.html","title":"Aggregators & Launchpads 聚合器与代币首发平台","g":"web3","isDef":1},{"term":"AI × Web3 AI × Web3 AI × Web3","name":"","def":"将人工智能（AI）的推理与自动化能力和区块链的去中心化激励、密码学验证与链上支付体系相结合的交叉技术方向。","path":"learn/218-zh.html","title":"AI × Web3 AI × Web3 AI × Web3","g":"web3","isDef":1},{"term":"Airdrops & Sybil Attacks","name":"空投与女巫攻击","def":"空投（Airdrop）是项目方把代币免费分发给符合条件的地址，常见依据是过去使用过产品（追溯性空投）或完成任务、积累积分。","path":"learn/200-zh.html","title":"Airdrops & Sybil Attacks 空投与女巫攻击","g":"web3","isDef":1},{"term":"ALMA","name":"阿诺勒古均线","def":"用加权后的平滑价格帮助看方向，同时尽量少被单根 K 线扰动。","path":"learn/50-zh.html","title":"ALMA 阿诺勒古均线","g":"market","isDef":1},{"term":"Anchored VWAP","name":"锚定 VWAP","def":"锚定VWAP是在你指定的起点之后，计算按成交量加权的平均价格。","path":"learn/93-zh.html","title":"Anchored VWAP 锚定 VWAP","g":"market","isDef":1},{"term":"Aroon","name":"阿隆指标","def":"观察最近的新高和新低离现在有多久。","path":"learn/43-zh.html","title":"Aroon 阿隆指标","g":"market","isDef":1},{"term":"Aroon Oscillator","name":"阿隆振荡器","def":"把 Aroon 两条线的领先关系压缩成一条：Up 减去 Down。","path":"learn/44-zh.html","title":"Aroon Oscillator 阿隆振荡器","g":"market","isDef":1},{"term":"ATR","name":"平均真实波幅","def":"ATR衡量最近每根K线通常能活动多大，包含本根高低差和相对昨收的跳空。","path":"learn/27-zh.html","title":"ATR 平均真实波幅","g":"market","isDef":1},{"term":"ATR Trailing Stop","name":"跟踪止损","def":"ATR跟踪止损用近期常见的价格晃动给持仓留空间，并在价格有利发展时移动退出参考。","path":"learn/91-zh.html","title":"ATR Trailing Stop 跟踪止损","g":"market","isDef":1},{"term":"ATR Trailing Stop ATR","name":"跟踪止损","def":"把近期平均真实波幅ATR乘以固定倍数留在价格后方作为动态保护线的工具","path":"learn/91-zh.html","title":"ATR Trailing Stop 跟踪止损","g":"market"},{"term":"ATRP/NATR","name":"百分比波幅","def":"ATRP/NATR常把ATR除以收盘价再乘100，回答‘通常的单根活动相当于价格的百分之几’。","path":"learn/28-zh.html","title":"ATRP/NATR 百分比波幅","g":"market","isDef":1},{"term":"Averaging Down vs Adding to Winners","name":"补仓与加仓","def":"补仓（摊低成本）：持仓亏损时以更低的价格再买入，使平均成本下降。","path":"learn/171-zh.html","title":"Averaging Down vs Adding to Winners 补仓与加仓","g":"market","isDef":1},{"term":"Awesome Oscillator","name":"动量震荡指标","def":"简称AO，用K线高低点中点的5周期简单均价减去34周期简单均价画成的柱状图","path":"learn/63-zh.html","title":"Awesome Oscillator/AO","g":"market"},{"term":"Awesome Oscillator/AO","name":"","def":"比较较短与较长的高低中点平均价，观察短期方向相对长期是否增强。","path":"learn/63-zh.html","title":"Awesome Oscillator/AO","g":"market","isDef":1},{"term":"Backtesting & Overfitting","name":"回测与过拟合","def":"回测（Backtesting）是将明确的交易规则代入历史行情数据以模拟检验策略表现的方法；回测净收益 = 模拟总毛利 - 累计手续费 - 累计滑点损耗。","path":"learn/190-zh.html","title":"Backtesting & Overfitting 回测与过拟合","g":"market","isDef":1},{"term":"Basis & Premium","name":"基差与溢价","def":"本课按加密市场常见用法定义：基差 = 合约价格 − 现货价格（也有教材按现货 − 合约计算，看平台口径）；溢价率 = 基差 ÷ 现货价格。","path":"learn/163-zh.html","title":"Basis & Premium 基差与溢价","g":"market","isDef":1},{"term":"Beginner Safety: Scams & Money Management","name":"新手安全：骗局与资金管理","def":"常见骗局包括：承诺稳定高收益的投资项目或“带单”、冒充客服或熟人索要验证码与助记词、仿冒网站与应用（钓鱼）、由陌生人长期培养信任后引导投资的“杀猪盘”、以及拉高后抛售（拉盘砸盘）的喊单群。","path":"learn/183-zh.html","title":"Beginner Safety: Scams & Money Management 新手安全：骗局与资金管理","g":"web3","isDef":1},{"term":"Bitcoin vs Ethereum","name":"比特币与以太坊","def":"比特币（BTC）是第一条公链，总量上限 2100 万枚，约每 21 万个区块（大约四年）新增发行量减半，设计目标是简单、稳定的价值转移和储存。","path":"learn/197-zh.html","title":"Bitcoin vs Ethereum 比特币与以太坊","g":"web3","isDef":1},{"term":"Blockchain & the Trilemma","name":"区块链与不可能三角","def":"区块链是一本由许多节点共同保存、按时间顺序串起来的账本：一段时间内的交易被打包成一个“区块”，每个区块都带着上一个区块的哈希值（数据指纹），改动任何一页都会让后面的指纹全部对不上。","path":"learn/196-zh.html","title":"Blockchain & the Trilemma 区块链与不可能三角","g":"web3","isDef":1},{"term":"Bollinger %B","name":"布林百分比","def":"布林%B把价格位于上下轨的哪里变成坐标：下轨是0，中间约0.5，上轨是1。","path":"learn/23-zh.html","title":"Bollinger %B 布林百分比","g":"market","isDef":1},{"term":"Bollinger Bands","name":"布林带","def":"布林带画一条近期均价中线，再按价格分散程度画上下轨。","path":"learn/21-zh.html","title":"Bollinger Bands 布林带","g":"market","isDef":1},{"term":"Bollinger BandWidth","name":"布林带宽","def":"布林带宽BBW把上轨与下轨之间有多宽变成数字，常用(上轨−下轨)÷中轨×100。","path":"learn/22-zh.html","title":"Bollinger BandWidth 布林带宽","g":"market","isDef":1},{"term":"BOP","name":"均势指标","def":"看每根从开盘到收盘留下的净推进，占整根高低活动范围多少。","path":"learn/85-zh.html","title":"BOP 均势指标","g":"market","isDef":1},{"term":"Breakouts & Failed Breakouts","name":"突破与假突破","def":"突破：一根K线的收盘价越过此前区间的最高价（或最低价）。","path":"learn/131-zh.html","title":"Breakouts & Failed Breakouts 突破与假突破","g":"market","isDef":1},{"term":"Bridges & Oracles","name":"跨链桥与预言机","def":"跨链桥把资产从一条链“搬”到另一条链：常见做法是在原链锁定资产，再在目标链铸造等量的包装资产（Wrapped Token），因此桥的锁仓合约和签名者一旦被攻破，目标链上的包装资产就可能失去支撑。","path":"learn/202-zh.html","title":"Bridges & Oracles 跨链桥与预言机","g":"web3","isDef":1},{"term":"Bull/Bear Power","name":"多空力量","def":"Bull/Bear Power用最高价与最低价分别减同一条EMA，观察一根K线两端离近期平均有多远。","path":"learn/20-zh.html","title":"Bull/Bear Power 多空力量","g":"market","isDef":1},{"term":"Case-Shiller","name":"房价指数","def":"标普Case-Shiller房价指数（S&P CoreLogic / Cotality Case-Shiller Home Price Indices）由标普道琼斯指数公司按月发布，采用经济学家Karl Case与Robert Shiller开创的“重复销售法（Repeat-Sales Method）”，专门追踪同一套独栋住宅在历史上前后两次或多次转手时的真实价格变化。","path":"info/learn/46-zh.html","title":"Case-Shiller 房价指数","g":"info","isDef":1},{"term":"CCI","name":"顺势指标","def":"CCI衡量代表价格离近期平均有多远，并按平时偏离大小作调整。","path":"learn/15-zh.html","title":"CCI 顺势指标","g":"market","isDef":1},{"term":"Chaikin Oscillator","name":"蔡金振荡器","def":"观察 ADL 这条量价累计线的变化速度，而不是只看累计线升到多高。","path":"learn/79-zh.html","title":"Chaikin Oscillator 蔡金振荡器","g":"market","isDef":1},{"term":"Chande Kroll Stop","name":"钱德克罗止损","def":"Chande Kroll Stop把近期价格范围和波动大小整理成两条退出参考线。","path":"learn/90-zh.html","title":"Chande Kroll Stop 钱德克罗止损","g":"market","isDef":1},{"term":"Chandelier Exit","name":"吊灯止损","def":"吊灯止损帮助已经持仓的人思考：如果价格从近期高点退回多少，我要重新检查继续持有的理由？","path":"learn/89-zh.html","title":"Chandelier Exit 吊灯止损","g":"market","isDef":1},{"term":"Channel Lines & Overshoots","name":"通道线与超越","def":"在上升通道里，通道线是平行于趋势线、画在高点一侧的线。","path":"learn/136-zh.html","title":"Channel Lines & Overshoots 通道线与超越","g":"market","isDef":1},{"term":"Choppiness Index","name":"震荡指数","def":"区分价格是在原地绕圈，还是比较顺地朝一边走。","path":"learn/46-zh.html","title":"Choppiness Index 震荡指数","g":"market","isDef":1},{"term":"Climaxes & Exhaustion","name":"高潮与衰竭","def":"高潮（climax）：一段趋势末端连续出现异常大的同向K线，波幅明显大于此前平均水平（本课取前 20 根平均波幅的 2 倍以上），通常伴随放量。","path":"learn/137-zh.html","title":"Climaxes & Exhaustion 高潮与衰竭","g":"market","isDef":1},{"term":"CMF","name":"蔡金资金流","def":"把最近窗口的加权成交量，与同一窗口全部成交量比较，观察收盘偏上还是偏下的量价贡献。","path":"learn/78-zh.html","title":"CMF 蔡金资金流","g":"market","isDef":1},{"term":"CMO","name":"钱德动量","def":"比较观察窗口中上涨总幅与下跌总幅，了解哪一边累计推进更多。","path":"learn/59-zh.html","title":"CMO 钱德动量","g":"market","isDef":1},{"term":"Concentrated Liquidity & Liquidity Management","name":"集中流动性与流动性管理","def":"允许流动性提供者（LP）将资金指定部署在自定义价格区间（Ticks）内以大幅提升资金利用效率的做市机制，以及围绕区间调仓与无常损失对冲展开的流动性管理策略。","path":"learn/227-zh.html","title":"Concentrated Liquidity & Liquidity Management 集中流动性与流动性管理","g":"web3","isDef":1},{"term":"ConnorsRSI","name":"康纳斯 RSI","def":"把短期涨跌力度、连涨连跌的持续性、当天变化相对历史的罕见程度放在一起，识别短期伸展。","path":"learn/58-zh.html","title":"ConnorsRSI 康纳斯 RSI","g":"market","isDef":1},{"term":"Consensus & Chain Types","name":"共识机制与链的类型","def":"共识机制是一条链上互不信任的节点决定“下一个区块由谁写、写什么才算数”的规则加奖惩。","path":"learn/198-zh.html","title":"Consensus & Chain Types 共识机制与链的类型","g":"web3","isDef":1},{"term":"Coppock Curve","name":"科波克曲线","def":"在较长时间范围观察深度低迷后的动量是否回暖。","path":"learn/74-zh.html","title":"Coppock Curve 科波克曲线","g":"market","isDef":1},{"term":"Correlation Coefficient","name":"相关系数","def":"比较两个序列在过去窗口里是否一起升降。","path":"learn/56-zh.html","title":"Correlation Coefficient 相关系数","g":"market","isDef":1},{"term":"Cost Distribution (Chip Distribution)","name":"筹码分布","def":"筹码分布（成本分布）是一种估算：假设每天成交的部分按换手率“替换”旧持仓，把成交量分配到当天的价格区间，逐日累积并衰减旧筹码，得到“当前持有者的成本大致分布在哪些价位”。","path":"learn/162-zh.html","title":"Cost Distribution (Chip Distribution) 筹码分布","g":"market","isDef":1},{"term":"Covered Calls & Protective Puts","name":"备兑看涨与保护性看跌","def":"备兑看涨（Covered Call）指在持有足额标的现货（如每 100 股正股）的同时，卖出 1 张对应数量的看涨期权（Call），以放弃行权价之上的潜在涨幅为代价收取权利金，区别于无现货担保的裸卖看涨（见本站「Options Basics 期权入门」一课）。","path":"learn/212-zh.html","title":"Covered Calls & Protective Puts 备兑看涨与保护性看跌","g":"market","isDef":1},{"term":"CPI","name":"消费者物价指数","def":"跟踪美国城市居民购买一篮子商品和服务要花多少钱。","path":"info/learn/1-zh.html","title":"CPI 消费者物价指数","g":"info","isDef":1},{"term":"Cup and Handle","name":"杯柄形态","def":"杯柄：价格从一个高点（杯沿）回落，形成圆弧形的底部（杯身，而不是尖底），再回到接近原杯沿的位置；之后小幅回撤形成“柄”，柄的回撤幅度小于杯身深度的一半。","path":"learn/154-zh.html","title":"Cup and Handle 杯柄形态","g":"market","isDef":1},{"term":"Cutting Losses","name":"止损与认错","def":"止损：在开仓前写下“这笔交易被证明错了”的条件（失效点，可以是一个价格，也可以是一个收盘条件），条件出现就按计划平仓，不因为不想承认亏损而推迟。","path":"learn/170-zh.html","title":"Cutting Losses 止损与认错","g":"market","isDef":1},{"term":"CVD","name":"累积成交量差值","def":"累计成交量差额CVD把一根根差额记在同一本账上，看指定时间内正向还是负向活动更持续。","path":"learn/102-zh.html","title":"CVD 累积成交量差值","g":"market","isDef":1},{"term":"DAOs & On-Chain Governance","name":"与链上治理","def":"去中心化自治组织（DAO），指通过公开智能合约与治理代币投票共同管理国库资金与协议参数的组织形态，通常结合治理论坛、链下快照、时间锁与多签执行。","path":"learn/230-zh.html","title":"DAOs & On-Chain Governance 与链上治理","g":"web3","isDef":1},{"term":"Dark Cloud Cover & Piercing Pattern","name":"乌云盖顶与刺透","def":"乌云盖顶：前一根是长阳线；后一根冲高越过前一根最高价后回落，收成阴线，收盘低于前一根实体的中点、但高于前一根开盘价。","path":"learn/147-zh.html","title":"Dark Cloud Cover & Piercing Pattern 乌云盖顶与刺透","g":"market","isDef":1},{"term":"Darvas Box","name":"箱体理论","def":"达瓦斯箱体：价格创出新高后，若接下来连续 3 根K线都没有超过这个高点，该高点就是箱顶；箱顶确认后，若随后出现一个低点且接下来连续 3 根都没有跌破它，该低点就是箱底。","path":"learn/165-zh.html","title":"Darvas Box 箱体理论","g":"market","isDef":1},{"term":"DeFi Lending & Liquidation","name":"去中心化借贷与清算","def":"去中心化借贷协议（如 Aave、Compound）让用户存入资产赚取利息，或以存入资产作抵押借出其他资产。","path":"learn/206-zh.html","title":"DeFi Lending & Liquidation 去中心化借贷与清算","g":"web3","isDef":1},{"term":"DEMA","name":"双指数均线","def":"DEMA是‘双重指数移动平均’，但图上通常是一条合成线：2倍第一层EMA，减去第二次平滑的EMA。","path":"learn/7-zh.html","title":"DEMA 双指数均线","g":"market","isDef":1},{"term":"DePIN: Token-Incentivised Infrastructure","name":"用代币共建基础设施","def":"去中心化物理基础设施网络（DePIN），指通过代币激励引导全球个人或节点贡献无线热点、传感器、存储或算力等硬件资源，协同建设与运营物理基础设施的网络模式。","path":"learn/215-zh.html","title":"DePIN: Token-Incentivised Infrastructure 用代币共建基础设施","g":"web3","isDef":1},{"term":"DeSci: Decentralised Science","name":"去中心化科研","def":"去中心化科学（DeSci），指利用区块链、去中心化自治组织（DAO）、灵魂绑定凭证与知识产权代币化（IP-NFT）重构科研经费筹集、同行评审、数据开源与成果转化的运动。","path":"learn/219-zh.html","title":"DeSci: Decentralised Science 去中心化科研","g":"web3","isDef":1},{"term":"DEXs & AMMs","name":"去中心化交易所与自动做市商","def":"去中心化交易所（DEX）让用户直接用自己的钱包和智能合约交易，不需要把资产交给交易所托管。","path":"learn/205-zh.html","title":"DEXs & AMMs 去中心化交易所与自动做市商","g":"web3","isDef":1},{"term":"Divergence","name":"背离","def":"常规顶背离：价格的第二个摆动高点高于第一个，同一时刻对应的指标高点却低于第一个；常规底背离反之。","path":"learn/156-zh.html","title":"Divergence 背离","g":"market","isDef":1},{"term":"Dividends & Corporate Actions","name":"除权除息与公司行动","def":"除权除息（Ex-Dividend / Ex-Rights）是上市公司在实施现金分红或送转股时，按法定规则从股票市场价格中扣除分红价值或稀释股本的交易制度。","path":"learn/187-zh.html","title":"Dividends & Corporate Actions 除权除息与公司行动","g":"market","isDef":1},{"term":"DMI","name":"趋向指标","def":"把行情拆成方向和强度两件事看：+DI、−DI 比较上推和下压，ADX 检查这种优势是否持续。","path":"learn/42-zh.html","title":"DMI 趋向指标","g":"market","isDef":1},{"term":"Donchian","name":"唐奇安通道","def":"唐奇安通道把最近N根最高价和最低价画为上下边，中线取两者中点。","path":"learn/24-zh.html","title":"Donchian 唐奇安通道","g":"market","isDef":1},{"term":"Double Tops & Bottoms","name":"双顶与双底","def":"双顶：两个相近的摆动高点（第二个可以略高或略低，本课取相差不超过 1%），中间夹一个摆动低点；收盘跌破中间低点才算形态完成。","path":"learn/149-zh.html","title":"Double Tops & Bottoms 双顶与双底","g":"market","isDef":1},{"term":"DPO","name":"去趋势价格振荡器","def":"先减去较慢的价格背景，再回看局部价格高低循环。","path":"learn/70-zh.html","title":"DPO 去趋势价格振荡器","g":"market","isDef":1},{"term":"Dragon-Tiger List","name":"龙虎榜","def":"龙虎榜（法定名称：证券交易公开信息）是沪深北证券交易所在每个交易日收盘后，对当日涨跌幅偏离值、振幅、换手率或连续三个交易日累计偏离值达到《交易规则》规定阈值的异动证券，依法公开披露其成交金额最大的前五家证券营业部或交易单元名称及买卖金额的制度。","path":"learn/194-zh.html","title":"Dragon-Tiger List 龙虎榜","g":"market","isDef":1},{"term":"Earnings Season & Guidance","name":"财报季与业绩预期","def":"财报季是上市公司集中披露季度或年度财务报告的周期；业绩预期是华尔街分析师对营收与每股收益形成的平均共识（Consensus Estimates）；业绩指引（Guidance）是公司管理层对未来财务表现的前瞻性官方预测。","path":"learn/186-zh.html","title":"Earnings Season & Guidance 财报季与业绩预期","g":"market","isDef":1},{"term":"ECI","name":"雇佣成本指数","def":"衡量雇主雇一个人每小时支付的工资和福利成本怎样变。","path":"info/learn/9-zh.html","title":"ECI 雇佣成本指数","g":"info","isDef":1},{"term":"EIA","name":"原油库存","def":"EIA每周原油库存（EIA Weekly Crude Oil Inventories）由美国能源信息署（U.S. Energy Information Administration）在每周三美东时间10:30发布的《每周石油状况报告（Weekly Petroleum Status Report）》中公布，用来统计截至上周五的美国商业原油库存总量及周度增减桶数。","path":"info/learn/70-zh.html","title":"EIA 原油库存","g":"info","isDef":1,"more":[{"path":"info/learn/71-zh.html","title":"EIA 天然气库存"}]},{"term":"Elder Force Index","name":"艾尔德力度指数","def":"同时考虑涨跌的距离和参与成交的数量：价格变得多、量也大，力度值就更大。","path":"learn/81-zh.html","title":"Elder Force Index 艾尔德力度指数","g":"market","isDef":1},{"term":"EMA","name":"指数均线","def":"EMA也是把价格整理成平均线，但最近的收盘价分量更大，所以通常比同根数SMA更快转弯。","path":"learn/2-zh.html","title":"EMA 指数均线","g":"market","isDef":1},{"term":"Engulfing Patterns","name":"吞没形态","def":"看涨吞没：前一根是阴线，当根是阳线，当根实体完全覆盖前一根实体（当根开盘不高于前一根收盘、收盘高于前一根开盘）。","path":"learn/140-zh.html","title":"Engulfing Patterns 吞没形态","g":"market","isDef":1},{"term":"EOM/EMV","name":"简易波动指标","def":"观察价格中点移动了多少、范围多宽、成交量多少，判断同样移动是否花了较少成交量。","path":"learn/82-zh.html","title":"EOM/EMV 简易波动指标","g":"market","isDef":1},{"term":"Everyday Tools & Industry Jargon","name":"常用工具与行业黑话","def":"日常参与和研究 Web3 必备的五类基础工具（区块浏览器、数据看板、自托管钱包、多签钱包、测试网水龙头）以及高频社区与链上术语速查。","path":"learn/221-zh.html","title":"Everyday Tools & Industry Jargon 常用工具与行业黑话","g":"web3","isDef":1},{"term":"Exchange Risk: Lessons from Mt. Gox, FTX & Bybit","name":"中心化交易所风险","def":"中心化交易所（CEX）替用户托管资产并在内部撮合交易：你在交易所看到的余额，是交易所欠你的一笔账，而不是你链上钱包里的币。","path":"learn/199-zh.html","title":"Exchange Risk: Lessons from Mt. Gox, FTX & Bybit 中心化交易所风险","g":"web3","isDef":1},{"term":"Exchanges, Brokers & Trading Rules","name":"交易所、券商与交易规则","def":"交易所是撮合买卖的场所（如纽约证券交易所、纳斯达克、上海与深圳证券交易所），普通投资者通过券商开户下单。","path":"learn/176-zh.html","title":"Exchanges, Brokers & Trading Rules 交易所、券商与交易规则","g":"market","isDef":1},{"term":"Expectancy & Win Rate","name":"期望值与胜率","def":"期望值（每笔平均盈亏）= 胜率 × 平均盈利 −（1 − 胜率）× 平均亏损，其中平均亏损取正数。","path":"learn/172-zh.html","title":"Expectancy & Win Rate 期望值与胜率","g":"market","isDef":1},{"term":"FHFA","name":"房价指数","def":"FHFA房价指数（FHFA House Price Index，简称FHFA HPI）由美国联邦住房金融局（Federal Housing Finance Agency）按月及按季度发布，同样采用“重复销售法”追踪同一套独栋住宅的价格变化，但它的基础数据来源于房利美（Fannie Mae）和房地美（Freddie Mac）两家政府支持企业收购或担保的符合标准（Conforming）按揭贷款记录。","path":"info/learn/47-zh.html","title":"FHFA 房价指数","g":"info","isDef":1},{"term":"Fibonacci","name":"斐波那契回撤/扩展","def":"斐波那契回撤与扩展把一段明确的涨跌分成固定比例，帮你回答“价格回头走到了原路程的几成，或顺势冲出相当于原路程的几倍”。","path":"learn/96-zh.html","title":"Fibonacci 斐波那契回撤/扩展","g":"market","isDef":1},{"term":"Fisher Transform","name":"费舍尔变换","def":"把价格在近期范围里特别靠边的情况放大，让动量转弯更容易看见。","path":"learn/69-zh.html","title":"Fisher Transform 费舍尔变换","g":"market","isDef":1},{"term":"Flags & Pennants","name":"旗形与三角旗","def":"旗形：先有一段急速的“旗杆”（几根大K线），随后价格在一个与旗杆方向相反、小幅倾斜的平行通道里整理（旗面），整理回撤不超过旗杆的一半；三角旗的旗面是小型收敛三角形。","path":"learn/151-zh.html","title":"Flags & Pennants 旗形与三角旗","g":"market","isDef":1},{"term":"Funding Rate","name":"资金费率","def":"资金费率（Funding Rate）展示永续合约每隔固定时间在多空持仓者之间互付的费用比例，帮你回答“当前合约相对现货偏贵还是偏便宜，以及持仓跨结算点需付出还是收到费用”。","path":"learn/108-zh.html","title":"Funding Rate 资金费率","g":"market","isDef":1},{"term":"GameFi: On-Chain Game Economies","name":"链上游戏经济","def":"将区块链资产确权与去中心化金融机制融入电子游戏，使游戏角色、道具或代币可在链上持有与流转的赛道，涵盖早期边玩边赚（P2E）及后续链上游戏经济探索。","path":"learn/228-zh.html","title":"GameFi: On-Chain Game Economies 链上游戏经济","g":"web3","isDef":1},{"term":"Gaps","name":"缺口","def":"向上缺口：当根最低价高于前一根最高价，两根之间留下没有成交的价格区间；向下缺口反之。","path":"learn/138-zh.html","title":"Gaps 缺口","g":"market","isDef":1},{"term":"GDI","name":"国内总收入","def":"从生产过程赚到的工资、利润等收入加总看同一个经济体。","path":"info/learn/22-zh.html","title":"GDI 国内总收入","g":"info","isDef":1},{"term":"GDP","name":"国内生产总值","def":"美国境内一段时间生产的最终商品和服务总量，实际GDP尽量剔除价格上涨影响；它是经济产出的总账。","path":"info/learn/21-zh.html","title":"GDP 国内生产总值","g":"info","isDef":1},{"term":"Greeks I: Delta & Gamma","name":"希腊字母一：Delta 与 Gamma","def":"Delta（Δ）衡量标的资产价格每变动 1 个单位时，期权理论价格随之变动的幅度；看涨期权 Delta 位于 0 到 1 之间，看跌期权位于 -1 到 0 之间。","path":"learn/208-zh.html","title":"Greeks I: Delta & Gamma 希腊字母一：Delta 与 Gamma","g":"market","isDef":1},{"term":"Greeks II: Theta & Vega","name":"希腊字母二：Theta 与 Vega","def":"Theta（Θ）衡量在其他条件不变时，每经过 1 天时间流逝，期权理论价格因时间价值衰减而减少的金额（对期权买方通常显示为负数）。","path":"learn/209-zh.html","title":"Greeks II: Theta & Vega 希腊字母二：Theta 与 Vega","g":"market","isDef":1},{"term":"Hammer & Hanging Man","name":"锤子线与上吊线","def":"形状：下影线长度至少是实体的 2 倍，上影线很短（不超过实体），实体位于整根波幅的上部。","path":"learn/141-zh.html","title":"Hammer & Hanging Man 锤子线与上吊线","g":"market","isDef":1},{"term":"Harami","name":"孕线","def":"孕线：后一根K线的实体完全落在前一根实体的范围内（与边界相等也算），后一根实体小于前一根实体的一半，两根颜色通常相反。","path":"learn/146-zh.html","title":"Harami 孕线","g":"market","isDef":1},{"term":"Head & Shoulders","name":"头肩顶与头肩底","def":"头肩顶：三个摆动高点中，中间的“头”高于左右两个“肩”；两肩之间的两个低点连成颈线。","path":"learn/148-zh.html","title":"Head & Shoulders 头肩顶与头肩底","g":"market","isDef":1},{"term":"Heikin Ashi","name":"平均K线","def":"Heikin Ashi 用原始K线重新计算：HA 收盘 =（开 + 高 + 低 + 收）÷ 4；HA 开盘 =（前一根 HA 开盘 + 前一根 HA 收盘）÷ 2；HA 最高 = 原最高、HA 开盘、HA 收盘中的最大值；HA 最低取最小值。","path":"learn/159-zh.html","title":"Heikin Ashi 平均K线","g":"market","isDef":1},{"term":"Historical Volatility","name":"历史波动率","def":"历史波动率HV看过去每根收益率有多不稳定，常再换成年化百分比。","path":"learn/31-zh.html","title":"Historical Volatility 历史波动率","g":"market","isDef":1},{"term":"HMA","name":"赫尔均线","def":"HMA用几次加权平均组合，让平均线在保持平顺的同时尽量少迟到。","path":"learn/6-zh.html","title":"HMA 赫尔均线","g":"market","isDef":1},{"term":"Ichimoku","name":"一目均衡表","def":"用同一张图观察近期均衡位置、中期均衡位置和较宽的价格区域。","path":"learn/47-zh.html","title":"Ichimoku 一目均衡表","g":"market","isDef":1},{"term":"ICT","name":"交易方法","def":"ICT交易方法把纽约交易时段（Killzones）、前日高低点以及三根K线快速推进留下的“公允价值缺口（FVG）”组合成观察流程，帮你回答“在活跃时段内，价格是否在扫过前期高低点后走出带FVG的快速转向”。","path":"learn/124-zh.html","title":"ICT 交易方法","g":"market","isDef":1},{"term":"Implied Volatility, IV Rank & Volatility Crush","name":"隐含波动率、IV Rank 与波动率压缩","def":"隐含波动率（IV）是将期权当前市场成交价代入定价模型反推出来的年化预期波动率。","path":"learn/210-zh.html","title":"Implied Volatility, IV Rank & Volatility Crush 隐含波动率、IV Rank 与波动率压缩","g":"market","isDef":1},{"term":"Indexes & ETFs","name":"指数与 ETF","def":"股票指数用一篮子股票的价格计算出一个数字，代表某个市场或板块的整体表现，例如标普 500、纳斯达克 100、沪深 300。","path":"learn/178-zh.html","title":"Indexes & ETFs 指数与 ETF","g":"market","isDef":1},{"term":"Inside & Outside Bars","name":"内包线与外包线","def":"内包线是当根最高价低于前一根最高价、且最低价高于前一根最低价的K线；外包线是当根最高价高于前一根最高价、且最低价低于前一根最低价的K线。","path":"learn/129-zh.html","title":"Inside & Outside Bars 内包线与外包线","g":"market","isDef":1},{"term":"IPOs & New Listings","name":"新股申购与上市","def":"首次公开发行（IPO，Initial Public Offering）是私有企业首次向社会公众公开发售股票并在交易所挂牌交易的融资过程。","path":"learn/188-zh.html","title":"IPOs & New Listings 新股申购与上市","g":"market","isDef":1},{"term":"ISM","name":"制造业 PMI","def":"对制造业采购经理问订单、产出、就业等比上月好还是差，再合成指数。","path":"info/learn/23-zh.html","title":"ISM 制造业 PMI","g":"info","isDef":1,"more":[{"path":"info/learn/24-zh.html","title":"ISM 服务业 PMI"}]},{"term":"JOLTS","name":"职位空缺","def":"调查月最后一个工作日，企业仍有、可以在30天内开始且正在积极招聘的职位空缺。","path":"info/learn/18-zh.html","title":"JOLTS 职位空缺","g":"info","isDef":1,"more":[{"path":"info/learn/19-zh.html","title":"JOLTS 主动离职率"}]},{"term":"KAMA","name":"自适应均线","def":"观察一条会随行情是否顺畅而改变反应速度的平均线。","path":"learn/49-zh.html","title":"KAMA 自适应均线","g":"market","isDef":1},{"term":"Keltner","name":"肯特纳通道","def":"现代肯特纳通道通常以EMA为中线，以ATR的倍数决定上下距离。","path":"learn/25-zh.html","title":"Keltner 肯特纳通道","g":"market","isDef":1},{"term":"Keltner Channels","name":"肯特纳通道","def":"现代常用版本以20期EMA为中线、上下各加减若干倍ATR平均真实波幅画成的波动率通道","path":"learn/25-zh.html","title":"Keltner 肯特纳通道","g":"market"},{"term":"Klinger Oscillator","name":"克林格振荡器","def":"把成交量与价格方向、范围变化结合，再比较快慢变化，观察量价推动的节奏。","path":"learn/80-zh.html","title":"Klinger Oscillator 克林格振荡器","g":"market","isDef":1},{"term":"KST","name":"确然指标","def":"把四种长短的涨跌速度合成一条动量线，减少只看单一窗口的片面。","path":"learn/71-zh.html","title":"KST 确然指标","g":"market","isDef":1},{"term":"Layer 2 & Rollups","name":"二层网络与 Rollup","def":"二层网络（Layer 2）把大量交易放在主链之外执行，再把压缩后的结果和证明提交回主链（Layer 1），以降低手续费、提高速度，同时尽量继承主链的安全。","path":"learn/201-zh.html","title":"Layer 2 & Rollups 二层网络与 Rollup","g":"web3","isDef":1},{"term":"Limit-up Boards","name":"涨停板与连板","def":"涨停板（Limit-Up）是证券交易所在单日竞价交易中规定的证券价格相对前一日收盘价的最大允许上涨幅度（见本站「交易所、券商与交易规则」一课）；涨停价 = 四舍五入到最小报价单位(前一日收盘价 × (1 + 涨跌幅限制比例))。","path":"learn/195-zh.html","title":"Limit-up Boards 涨停板与连板","g":"market","isDef":1},{"term":"Linear Regression Channel","name":"回归通道","def":"把近期价格大方向和离中心的远近分开看。","path":"learn/53-zh.html","title":"Linear Regression Channel 回归通道","g":"market","isDef":1},{"term":"Linear Regression R²","name":"回归决定系数","def":"检查用直线概括这段价格到底合不合适。","path":"learn/55-zh.html","title":"Linear Regression R² 回归决定系数","g":"market","isDef":1},{"term":"Linear Regression Slope","name":"回归斜率","def":"把近期拟合直线的上斜或下斜量化，观察方向和速度有没有改变。","path":"learn/54-zh.html","title":"Linear Regression Slope 回归斜率","g":"market","isDef":1},{"term":"Liquidations","name":"已发生强平数据","def":"已发生强平数据（Liquidations）记录因确保金不足被平台强制平仓的合约金额或数量，帮你回答“刚才这波急涨急跌里，有多少被动爆仓的杠杆仓位被清退”。","path":"learn/110-zh.html","title":"Liquidations 已发生强平数据","g":"market","isDef":1},{"term":"Liquidity & Market Impact","name":"流动性与冲击成本","def":"流动性：在不明显改变价格的前提下买卖一定数量的能力，常用买卖价差、盘口挂单深度和成交量衡量。","path":"learn/174-zh.html","title":"Liquidity & Market Impact 流动性与冲击成本","g":"market","isDef":1},{"term":"Long/Short Accounts Ratio","name":"多空账户比","def":"多空账户比（Long/Short Accounts Ratio）把样本里“净做多账户人数”除以“净做空账户人数”，帮你回答“被统计的交易者里，站多头的账户多还是站空头的账户多”。","path":"learn/109-zh.html","title":"Long/Short Accounts Ratio 多空账户比","g":"market","isDef":1},{"term":"LPR","name":"贷款市场报价利率","def":"在中国，新闻里常说的“降息”往往涉及好几个利率：央行给商业银行的批发政策利率（如7天逆回购利率），以及商业银行给企业和居民放贷的零售基准——贷款市场报价利率（LPR）。","path":"info/learn/79-zh.html","title":"LPR 贷款市场报价利率","g":"info","isDef":1},{"term":"LSMA","name":"最小二乘均线","def":"看近期价格若用一条最贴近它们的直线概括，直线现在的末端在哪里。","path":"learn/52-zh.html","title":"LSMA 最小二乘均线","g":"market","isDef":1},{"term":"M2","name":"货币供应量","def":"M2货币供应量（M2 Money Stock）是美联储统计的广义流动性指标，汇总了实体经济中可直接用于支付的货币以及较容易转化为支付手段的近似货币资产。","path":"info/learn/55-zh.html","title":"M2 货币供应量","g":"info","isDef":1},{"term":"MA Cross","name":"均线交叉","def":"双均线把一段短期平均价和一段较长期平均价放在一起，比较近期相对过去是否更强。","path":"learn/9-zh.html","title":"MA Cross 均线交叉","g":"market","isDef":1},{"term":"MACD","name":"","def":"MACD把快EMA减慢EMA得到一条差值线，再用信号线平滑这个差；柱子显示两线之间还差多少。","path":"learn/12-zh.html","title":"MACD","g":"market","isDef":1},{"term":"MACD-V","name":"","def":"把快慢均价之差放到日常波动尺度里比较。","path":"learn/75-zh.html","title":"MACD-V","g":"market","isDef":1},{"term":"Margin Financing Balance","name":"融资融券余额","def":"融资融券余额（Margin Financing and Securities Lending Balance）是市场上投资者向证券公司借入资金买入证券（融资）与借入证券卖出（融券）尚未偿还的累计存量总和。","path":"learn/193-zh.html","title":"Margin Financing Balance 融资融券余额","g":"market","isDef":1},{"term":"Mass Index","name":"质量指数","def":"观察每根 K 线最高到最低的活动范围是否先扩大再缓和。","path":"learn/76-zh.html","title":"Mass Index 质量指数","g":"market","isDef":1},{"term":"MBA","name":"抵押贷款申请","def":"MBA每周抵押贷款申请调查（MBA Weekly Mortgage Applications Survey）由美国抵押贷款银行家协会（Mortgage Bankers Association）于每周三上午发布，用来统计截至上周五的一周内，美国居民向商业银行、储蓄机构和房贷公司提交的独栋住宅按揭贷款申请数量变化。","path":"info/learn/48-zh.html","title":"MBA 抵押贷款申请","g":"info","isDef":1},{"term":"McGinley Dynamic","name":"麦金利动态线","def":"用一条追赶速度会随价格关系调整的动态线，看价格的大致方向和偏离程度。","path":"learn/51-zh.html","title":"McGinley Dynamic 麦金利动态线","g":"market","isDef":1},{"term":"Measured Moves","name":"等距运动","def":"等距运动（Measured Move）：把第一段走势（A 到 B）的价格幅度，从回调结束点 C 开始向同一方向复制一次，得到参考价 D = C + (B − A)（上涨）或 D = C − (A − B)（下跌）。","path":"learn/135-zh.html","title":"Measured Moves 等距运动","g":"market","isDef":1},{"term":"MFI","name":"资金流量指数","def":"MFI把代表价格的上升下降与成交量结合，转成0到100的分数。","path":"learn/19-zh.html","title":"MFI 资金流量指数","g":"market","isDef":1},{"term":"Momentum","name":"动量指标","def":"MTM或Momentum的常见差值版，用当前收盘减N根前收盘，直接显示相隔这段时间差了多少钱。","path":"learn/17-zh.html","title":"Momentum 动量指标","g":"market","isDef":1},{"term":"Morning & Evening Stars","name":"早晨之星与黄昏之星","def":"早晨之星：第一根是长阴线；第二根是实体小于第一根实体三分之一的“星线”；第三根是阳线，收盘高于第一根实体的中点。","path":"learn/144-zh.html","title":"Morning & Evening Stars 早晨之星与黄昏之星","g":"market","isDef":1},{"term":"Moving Average Alignment","name":"均线多空排列","def":"均线多头排列：短期均线在中期均线之上、中期在长期之上（如 MA5 > MA10 > MA20），且三条均线都在上升；空头排列反之。","path":"learn/168-zh.html","title":"Moving Average Alignment 均线多空排列","g":"market","isDef":1},{"term":"Moving Average Envelopes","name":"均线包络线","def":"均线包络先画平均线，再向上和向下各偏移固定百分比。","path":"learn/26-zh.html","title":"Moving Average Envelopes 均线包络线","g":"market","isDef":1},{"term":"Moving Average Ribbon","name":"均线带","def":"均线带把好几种长度的平均价画成一束，便于看短、中、较长的价格方向是否一致。","path":"learn/10-zh.html","title":"Moving Average Ribbon 均线带","g":"market","isDef":1},{"term":"Multi-timeframe Analysis","name":"多周期分析","def":"多周期分析：用较大周期判断背景（趋势方向和关键价位），再用较小周期观察价格在这些位置的具体表现。","path":"learn/139-zh.html","title":"Multi-timeframe Analysis 多周期分析","g":"market","isDef":1},{"term":"NAHB","name":"房屋建筑商信心指数","def":"NAHB房产市场指数由全美住宅建筑商协会（NAHB）按月发布，通过问卷调查全美独栋住宅建筑商对“当前新房销售状况”、“未来六个月新房销售预期”以及“潜在买家看房客流（Traffic）”三个维度的景气评价。","path":"info/learn/50-zh.html","title":"NAHB 房屋建筑商信心指数","g":"info","isDef":1},{"term":"New Highs/New Lows","name":"新高新低广度","def":"新高新低家数统计一群股票里，有多少创指定时期的新高、有多少创新低。","path":"learn/105-zh.html","title":"New Highs/New Lows 新高新低广度","g":"market","isDef":1},{"term":"New Token Standards: ERC-404, 6551, 3525","name":"新代币标准：ERC-404、6551、3525","def":"在以太坊同质化代币（ERC-20）与非同质化代币（ERC-721）基础上演进出的新型资产协议，分别探索图币混合流动性（ERC-404）、代币绑定账户（ERC-6551）与半同质化金融凭证（ERC-3525）。","path":"learn/217-zh.html","title":"New Token Standards: ERC-404, 6551, 3525 新代币标准：ERC-404、6551、3525","g":"web3","isDef":1},{"term":"NVI","name":"负量指标","def":"单独记录缩量那些时段的价格表现。","path":"learn/84-zh.html","title":"NVI 负量指标","g":"market","isDef":1},{"term":"OBV","name":"能量潮","def":"OBV按收盘涨跌给成交量记分：比上一根收得高就加整根量，低就减整根量，持平通常不变。","path":"learn/34-zh.html","title":"OBV 能量潮","g":"market","isDef":1},{"term":"On-Chain Derivatives","name":"链上衍生品","def":"部署在区块链智能合约或应用链上的衍生品协议，主要提供无需交割日的永续合约交易，通过链上抵押按金托管与公开清算规则实现去中心化杠杆与对冲。","path":"learn/224-zh.html","title":"On-Chain Derivatives 链上衍生品","g":"web3","isDef":1},{"term":"On-Chain Identity: DID & SBT","name":"链上身份：DID 与 SBT","def":"去中心化标识符（DID）是由用户自主掌握私钥与验证方法的数字身份标准；灵魂绑定代币（SBT）则是绑定在特定账户上、不可转让的链上凭证，用于记录资历、信誉或成员身份。","path":"learn/216-zh.html","title":"On-Chain Identity: DID & SBT 链上身份：DID 与 SBT","g":"web3","isDef":1},{"term":"Open Interest","name":"未平仓量","def":"未平仓量（Open Interest，简称OI）统计期货或永续合约市场里“当前尚有多少张已开立但未平掉的生效合约”，帮你回答“场内合约总规模是在增加还是减少”。","path":"learn/107-zh.html","title":"Open Interest 未平仓量","g":"market","isDef":1},{"term":"Operations & Business Roles in Web3","name":"运营与商务岗位全景","def":"围绕 Web3 协议的社区建设、用户增长、内容研究、生态商务拓展（BD）与去中心化治理协调所形成的非技术职业体系。","path":"learn/223-zh.html","title":"Operations & Business Roles in Web3 运营与商务岗位全景","g":"web3","isDef":1},{"term":"Options Basics","name":"期权入门","def":"期权（Options）是赋予买方在约定到期日或之前以约定行权价（Strike Price）买入或卖出标的资产权利而非义务的标准化金融衍生合约。","path":"learn/189-zh.html","title":"Options Basics 期权入门","g":"market","isDef":1},{"term":"Order Book Depth & Liquidity Heatmaps","name":"盘口深度与流动性热力图","def":"盘口深度（订单簿）列出各价位上尚未成交的买单和卖单数量；流动性热力图把这些挂单随时间画成颜色，颜色越亮代表该价位挂单越多。","path":"learn/164-zh.html","title":"Order Book Depth & Liquidity Heatmaps 盘口深度与流动性热力图","g":"market","isDef":1},{"term":"Parabolic SAR","name":"抛物线指标","def":"抛物线SAR在价格上下画点，按一套加速规则跟踪当前算法方向。","path":"learn/38-zh.html","title":"Parabolic SAR 抛物线指标","g":"market","isDef":1},{"term":"PCE","name":"物价指数","def":"衡量美国居民消费相关商品和服务的价格，覆盖范围和权重与CPI不同，例如包含部分由雇主、政府替居民支付的医疗消费。","path":"info/learn/3-zh.html","title":"PCE 物价指数","g":"info","isDef":1},{"term":"Percent Above MA","name":"均线上方股票占比","def":"均线上方家数占比看一群股票里，多少站在各自的平均价格之上。","path":"learn/106-zh.html","title":"Percent Above MA 均线上方股票占比","g":"market","isDef":1},{"term":"Pin Bars","name":"长影线反转K","def":"Pin Bar 是单根K线：主影线长度大于实体长度的两倍，实体靠近波幅的一端，反向影线很短或没有；看涨 Pin Bar 是长下影线加靠近上端的实体，看跌 Pin Bar 是长上影线加靠近下端的实体。","path":"learn/130-zh.html","title":"Pin Bars 长影线反转K","g":"market","isDef":1},{"term":"Pivot Points","name":"标准枢轴点","def":"枢轴标准点用上一段已经完成的高、低、收盘价，为下一段画一组水平路标。","path":"learn/94-zh.html","title":"Pivot Points 标准枢轴点","g":"market","isDef":1},{"term":"Pivot Points High/Low","name":"高低点枢轴","def":"局部高低点指标把一段价格里的小山峰和小山谷标出来。","path":"learn/95-zh.html","title":"Pivot Points High/Low 高低点枢轴","g":"market","isDef":1},{"term":"Pivot Points Standard","name":"标准枢轴点","def":"用上一周期的最高价、最低价和收盘价按固定算式算出一组水平参考线画在当前周期图上的工具","path":"learn/94-zh.html","title":"Pivot Points 标准枢轴点","g":"market"},{"term":"Placing Orders: Market vs Limit","name":"下单基础：市价单与限价单","def":"市价单：按当时能成交的最好价格立即成交，优先保证成交、不保证价格。","path":"learn/177-zh.html","title":"Placing Orders: Market vs Limit 下单基础：市价单与限价单","g":"market","isDef":1},{"term":"PMO","name":"价格动量振荡器","def":"观察百分比涨跌速度经过两次平滑后，是偏上、偏下还是放慢。","path":"learn/73-zh.html","title":"PMO 价格动量振荡器","g":"market","isDef":1},{"term":"Point & Figure Charts","name":"点数图","def":"点数图用 X 列记录上涨、O 列记录下跌，每个格子代表一个固定价格幅度（格值）。","path":"learn/161-zh.html","title":"Point & Figure Charts 点数图","g":"market","isDef":1},{"term":"PPI","name":"生产者物价指数","def":"跟踪美国国内生产者出售商品和服务收到的价格。","path":"info/learn/5-zh.html","title":"PPI 生产者物价指数","g":"info","isDef":1},{"term":"PPO","name":"价格百分比振荡器","def":"PPO把快慢EMA的差除以慢EMA，变成百分比。","path":"learn/18-zh.html","title":"PPO 价格百分比振荡器","g":"market","isDef":1},{"term":"Prediction Markets & InfoFi","name":"预测市场与 InfoFi","def":"信息金融（InfoFi），指利用链上预测市场、注意力激励或声誉质押等金融机制对现实事件概率与信息价值进行发现、定价与验证的赛道。","path":"learn/231-zh.html","title":"Prediction Markets & InfoFi 预测市场与 InfoFi","g":"web3","isDef":1},{"term":"Price Relative","name":"相对表现","def":"价格相对强弱用A价格除以B价格，观察比值是升还是降。","path":"learn/40-zh.html","title":"Price Relative 相对表现","g":"market","isDef":1},{"term":"Pring Special K","name":"","def":"同时汇总很多短、中、长窗口的涨跌速度，观察更宽时间范围内的动力背景。","path":"learn/72-zh.html","title":"Pring Special K","g":"market","isDef":1},{"term":"Pullbacks & Second Entries","name":"回调与二次入场","def":"在上涨趋势的回调里，第一根最高价高于前一根最高价的K线叫 H1（High 1）；之后回调继续创出新低，再出现一根最高价高于前一根最高价的K线叫 H2，也就是“二次入场”的信号K位置。","path":"learn/132-zh.html","title":"Pullbacks & Second Entries 回调与二次入场","g":"market","isDef":1},{"term":"PVI","name":"正量指标","def":"单独记录放量那些时段的价格表现。","path":"learn/83-zh.html","title":"PVI 正量指标","g":"market","isDef":1},{"term":"PVO","name":"成交量百分比振荡器","def":"PVO比较短期平均成交量比长期平均成交量高或低多少百分比。","path":"learn/36-zh.html","title":"PVO 成交量百分比振荡器","g":"market","isDef":1},{"term":"PVT","name":"量价趋势","def":"PVT把每根收盘相对上一根的百分比变化乘成交量，再累计起来。","path":"learn/35-zh.html","title":"PVT 量价趋势","g":"market","isDef":1},{"term":"RCI","name":"排名相关指数","def":"检查价格高低排名是否与时间先后排列一致。","path":"learn/68-zh.html","title":"RCI 排名相关指数","g":"market","isDef":1},{"term":"Reading Financial Statements","name":"读懂三张财报","def":"三张财报是基于会计准则编制的核心报告体系：利润表（净利润 = 营业收入 - 营业成本 - 期间费用 - 税费）反映特定期间的经营盈亏；资产负债表（资产 = 负债 + 所有者权益）反映特定时点的财务状况；现金流量表（期末现金 = 期初现金 + 经营/投资/筹资活动现金净流量）反映特定期间真实的现金流入与流出。","path":"learn/184-zh.html","title":"Reading Financial Statements 读懂三张财报","g":"market","isDef":1},{"term":"Rectangles","name":"矩形整理","def":"矩形：价格在两条大致水平的线之间来回，上沿至少触及两次、下沿至少触及两次，形成一个箱体；收盘越过上沿或下沿才算突破。","path":"learn/152-zh.html","title":"Rectangles 矩形整理","g":"market","isDef":1},{"term":"Relative Vigor Index","name":"相对活力指数","def":"比较收盘相对开盘的净推进，和每根 K 线整个活动范围，观察一段时间是否经常朝同一边收盘。","path":"learn/66-zh.html","title":"Relative Vigor Index 相对活力指数","g":"market","isDef":1},{"term":"Relative Volatility Index","name":"相对波动指数","def":"比较向上与向下阶段的价格波动哪一侧更占优势。","path":"learn/67-zh.html","title":"Relative Volatility Index 相对波动指数","g":"market","isDef":1},{"term":"Relative Volume at Time","name":"同时段相对成交量","def":"同时段相对成交量帮你回答：现在比过去同一个时间段热闹多少？","path":"learn/86-zh.html","title":"Relative Volume at Time 同时段相对成交量","g":"market","isDef":1},{"term":"Renko Charts","name":"砖形图","def":"Renko 砖形图只在价格走完一个固定幅度（砖块大小）时画一块砖：收盘比上一块砖的顶部高出至少一块砖，就向上画砖；比底部低出至少两块砖（反向需要两块）才向下画砖。","path":"learn/160-zh.html","title":"Renko Charts 砖形图","g":"market","isDef":1},{"term":"Rising & Falling Wedges","name":"楔形形态","def":"上升楔形：摆动高点和摆动低点都在抬高，但低点抬高得更快，两条连线向上收敛；收盘跌破下边线为向下突破。","path":"learn/153-zh.html","title":"Rising & Falling Wedges 楔形形态","g":"market","isDef":1},{"term":"ROC","name":"变动率","def":"ROC直接问‘现在比N根以前涨跌了百分之几’。","path":"learn/16-zh.html","title":"ROC 变动率","g":"market","isDef":1},{"term":"Rounding Bottoms & V Reversals","name":"圆弧底与 V 形反转","def":"圆弧底：下跌逐渐放缓、在低位横向停留较长时间，再逐渐回升，形成平缓的 U 形；V 形反转：急跌之后几乎没有停留就急涨，本课以“8 根K线内下跌超过 4%，随后 8 根K线内收复跌幅的 80% 以上”作为识别口径。","path":"learn/155-zh.html","title":"Rounding Bottoms & V Reversals 圆弧底与 V 形反转","g":"market","isDef":1},{"term":"RSI","name":"相对强弱指数","def":"RSI把最近上涨与下跌的平均幅度转成0到100的分数。","path":"learn/11-zh.html","title":"RSI 相对强弱指数","g":"market","isDef":1},{"term":"RVOL","name":"相对成交量","def":"相对成交量RVOL把当前量除以平常量，回答‘现在有平时几倍热闹’。","path":"learn/33-zh.html","title":"RVOL 相对成交量","g":"market","isDef":1},{"term":"RWA: Real-World Assets On-Chain","name":"现实资产上链","def":"将国债、房地产、应收账款等链下传统资产的所有权或收益权通过法律架构与智能合约映射为链上代币，使其可在区块链上持有、流转与组合的模式。","path":"learn/214-zh.html","title":"RWA: Real-World Assets On-Chain 现实资产上链","g":"web3","isDef":1},{"term":"Seasonality & Calendar Effects","name":"季节性与日历效应","def":"季节性与日历效应（Seasonality & Calendar Effects）是指金融资产收益率在特定月份、季度、星期或节假日前后呈现出历史统计均值偏离的日历异象（Calendar Anomalies）。","path":"learn/192-zh.html","title":"Seasonality & Calendar Effects 季节性与日历效应","g":"market","isDef":1},{"term":"Shooting Star & Inverted Hammer","name":"射击之星与倒锤子","def":"形状：上影线长度至少是实体的 2 倍，下影线很短（不超过实体），实体位于整根波幅的下部。","path":"learn/142-zh.html","title":"Shooting Star & Inverted Hammer 射击之星与倒锤子","g":"market","isDef":1},{"term":"SLOOS","name":"银行信贷标准调查","def":"高级贷款专员意见调查（SLOOS，Senior Loan Officer Opinion Survey on Bank Lending Practices）是美联储通常每季度开展一次的定性问卷调查，直接向美国本土大型与中小型商业银行及外资银行驻美分支机构的信贷主管提问：过去三个月贵行放贷审批门槛是收紧了还是放宽了？","path":"info/learn/58-zh.html","title":"SLOOS 银行信贷标准调查","g":"info","isDef":1},{"term":"SMA","name":"简单均线","def":"SMA把最近一段价格压成一条平均线，帮你回答‘最近整体是在抬高、降低，还是原地打转’。","path":"learn/1-zh.html","title":"SMA 简单均线","g":"market","isDef":1},{"term":"Smart Contracts & Token Approvals","name":"智能合约与代币授权","def":"智能合约是部署在区块链上、满足条件就自动执行的程序。","path":"learn/203-zh.html","title":"Smart Contracts & Token Approvals 智能合约与代币授权","g":"web3","isDef":1},{"term":"SMC","name":"智能资金概念","def":"SMC把前高前低、结构突破（BOS/CHOCH）及快速推进前的反向K线串成看图流程，帮你回答“价格刺穿前高前低后是否转向，以及回踩哪片起始区值得观察”。","path":"learn/123-zh.html","title":"SMC 智能资金概念","g":"market","isDef":1},{"term":"SMI","name":"随机动量指数","def":"看收盘位于近期高低范围的上半还是下半，再把变化平滑。","path":"learn/64-zh.html","title":"SMI 随机动量指数","g":"market","isDef":1},{"term":"SMI Ergodic","name":"遍历指标","def":"用平滑后的净涨跌与总涨跌幅比较，读出方向动力，并用慢信号线观察动力有没有改善。","path":"learn/65-zh.html","title":"SMI Ergodic 遍历指标","g":"market","isDef":1},{"term":"SMMA/RMA","name":"平滑均线","def":"SMMA/RMA让新价格一点点进入旧平均，常见RMA每根只给新价1/N的分量。","path":"learn/4-zh.html","title":"SMMA/RMA 平滑均线","g":"market","isDef":1},{"term":"SocialFi: Tokenising Social Graphs","name":"社交关系代币化","def":"将去中心化身份、链上社交图谱与代币经济机制融入社交网络，使创作者与用户能够自主拥有社交关系并探索内容、关注度与影响力资产化的赛道。","path":"learn/229-zh.html","title":"SocialFi: Tokenising Social Graphs 社交关系代币化","g":"web3","isDef":1},{"term":"SOFR","name":"融资利率","def":"担保隔夜融资利率（SOFR，Secured Overnight Financing Rate）是由纽约联储与美国财政部金融研究办公室（OFR）共同编制发布的基准利率，汇总衡量金融机构以美国国债作为抵押品、在回购市场（Repo Market）借入隔夜美元现金的实际成交利息成本。","path":"info/learn/59-zh.html","title":"SOFR 融资利率","g":"info","isDef":1},{"term":"SOS","name":"强势信号","def":"收盘站上 105.17","path":"learn/118-zh.html","title":"威科夫方法","g":"market"},{"term":"Spot, Margin & Leveraged Contracts","name":"现货、杠杆与合约","def":"现货：用全额资金买入资产本身，价格跌了只是浮亏，不会被强制卖出（借钱买入的除外）。","path":"learn/182-zh.html","title":"Spot, Margin & Leveraged Contracts 现货、杠杆与合约","g":"web3","isDef":1},{"term":"Stablecoins Basics","name":"稳定币入门","def":"稳定币是目标价格锚定某种资产（最常见的是 1 美元）的加密代币。","path":"learn/181-zh.html","title":"Stablecoins Basics 稳定币入门","g":"web3","isDef":1},{"term":"Staking, Liquid Staking & Restaking","name":"质押、流动性质押与再质押","def":"质押是把代币锁定在权益证明网络中参与验证、获得奖励。","path":"learn/207-zh.html","title":"Staking, Liquid Staking & Restaking 质押、流动性质押与再质押","g":"web3","isDef":1},{"term":"Standard Deviation","name":"标准差指标","def":"价格标准差把最近一组价格离平均值有多分散概括成一个数。","path":"learn/30-zh.html","title":"Standard Deviation 标准差指标","g":"market","isDef":1},{"term":"Stochastic/KD","name":"随机指标","def":"KD随机指标看收盘价位于最近最高与最低之间的什么位置：越靠近期顶部，读数越高；越靠底部，越低。","path":"learn/13-zh.html","title":"Stochastic/KD 随机指标","g":"market","isDef":1},{"term":"StochRSI","name":"随机 RSI","def":"判断 RSI 这把涨跌力度尺，目前在它自己最近的范围里靠上还是靠下。","path":"learn/57-zh.html","title":"StochRSI 随机 RSI","g":"market","isDef":1},{"term":"Supertrend","name":"超级趋势","def":"Supertrend用ATR和倍数在价格一侧画跟踪线，达到翻转条件后换到另一侧。","path":"learn/39-zh.html","title":"Supertrend 超级趋势","g":"market","isDef":1},{"term":"TD Sequential","name":"九转序列","def":"TD Sequential 分两步。","path":"learn/158-zh.html","title":"TD Sequential 九转序列","g":"market","isDef":1},{"term":"Technical Roles in Web3","name":"技术岗位全景","def":"围绕区块链协议、智能合约、安全审计与去中心化应用前后端开发所形成的技术职业体系，分为链上原生研发与 Web2.5 融合工程两大路径。","path":"learn/222-zh.html","title":"Technical Roles in Web3 技术岗位全景","g":"web3","isDef":1},{"term":"TEMA","name":"三指数均线","def":"TEMA把三层EMA按3×第一层−3×第二层+第三层合成一条价格线，目的是减少平均线的迟到。","path":"learn/8-zh.html","title":"TEMA 三指数均线","g":"market","isDef":1},{"term":"The Doji Family","name":"十字星家族","def":"十字星：实体小于整根波幅的 10%。","path":"learn/143-zh.html","title":"The Doji Family 十字星家族","g":"market","isDef":1},{"term":"Three White Soldiers & Three Black Crows","name":"三白兵与三乌鸦","def":"三白兵：连续三根阳线，每根收盘都高于前一根收盘，每根上影线都不超过本根波幅的 30%（收在高位附近）。","path":"learn/145-zh.html","title":"Three White Soldiers & Three Black Crows 三白兵与三乌鸦","g":"market","isDef":1},{"term":"Tokenomics: Supply, FDV & Unlocks","name":"代币经济学：供应、FDV 与解锁","def":"代币经济学研究代币如何发行、分配、释放和被使用。","path":"learn/204-zh.html","title":"Tokenomics: Supply, FDV & Unlocks 代币经济学：供应、FDV 与解锁","g":"web3","isDef":1},{"term":"TPO/Market Profile","name":"市场轮廓","def":"TPO把交易日按固定时间块切片，记录每个价位被多少个时间段访问过，帮你回答“价格在哪里停留时间最久、在哪里一闪而过”。","path":"learn/100-zh.html","title":"TPO/Market Profile 市场轮廓","g":"market","isDef":1},{"term":"Trading Plan & Journal","name":"交易计划与交易日志","def":"交易计划（Trading Plan）是开仓前制定的书面行动契约，包含交易标的、触发条件、仓位上限（单笔可承受亏损金额 ÷ 每股止损空间）、失效止损位与止盈退出规则；交易日志（Trading Journal）是盘后客观记录每笔交易执行要素、偏差原因与情绪状态的统计档案。","path":"learn/191-zh.html","title":"Trading Plan & Journal 交易计划与交易日志","g":"market","isDef":1},{"term":"Trading Psychology & Biases","name":"交易心理与常见偏差","def":"交易中的常见认知偏差包括：赌徒谬误（以为连涨之后“该跌了”、连亏之后“该赚了”）、损失厌恶（同样金额，亏损带来的痛苦大于盈利带来的快乐）、处置效应（太早卖出盈利单、太久持有亏损单）、锚定（拿过去的价格判断现在贵或便宜）和事后诸葛亮（把事后的解释当成事前可以预见）。","path":"learn/173-zh.html","title":"Trading Psychology & Biases 交易心理与常见偏差","g":"market","isDef":1},{"term":"Trading Ranges","name":"交易区间","def":"交易区间：一段K线中，价格反复在大致固定的上下边界之间来回，没有持续创出更高的高点和更高的低点（或更低的高点和更低的低点）。","path":"learn/134-zh.html","title":"Trading Ranges 交易区间","g":"market","isDef":1},{"term":"Trend Bars & Doji","name":"趋势K与十字星","def":"趋势K是实体占整根波幅大部分、收盘靠近波幅一端的K线；十字星是开盘价与收盘价非常接近、实体很小的K线，本课以实体小于整根波幅的十分之一作为十字星的参考口径。","path":"learn/128-zh.html","title":"Trend Bars & Doji 趋势K与十字星","g":"market","isDef":1},{"term":"Trend vs Range","name":"趋势与震荡的判断","def":"趋势：在一段K线里，摆动高点和低点同向推进（上涨中更高的高点与更高的低点），收盘大多在一侧，均线方向明确。","path":"learn/169-zh.html","title":"Trend vs Range 趋势与震荡的判断","g":"market","isDef":1},{"term":"Triangles","name":"三角形","def":"三角形：价格的摆动高点和摆动低点各连成一条线，两线向右收敛。","path":"learn/150-zh.html","title":"Triangles 三角形","g":"market","isDef":1},{"term":"Triple Screen","name":"三重滤网","def":"三重滤网用三个相差约 5 倍的周期分工：第一层（长周期，如周线）用趋势指标确定方向，只做该方向；第二层（中周期，如日线）用振荡指标找逆向回调，例如上升趋势中振荡指标进入超卖；第三层（短周期或盘中）用价格本身决定入场，例如在前一根高点上方设置买入止损单。","path":"learn/167-zh.html","title":"Triple Screen 三重滤网","g":"market","isDef":1},{"term":"TRIX","name":"","def":"看经过三次平滑的价格，最近变化速度是正还是负。","path":"learn/61-zh.html","title":"TRIX","g":"market","isDef":1},{"term":"True Strength Index","name":"真实强弱指数","def":"把逐根涨跌平滑后，与全部变化幅度比较，观察净动力朝上还是朝下。","path":"learn/60-zh.html","title":"True Strength Index 真实强弱指数","g":"market","isDef":1},{"term":"TTM Squeeze","name":"波动挤压","def":"TTM Squeeze把两个问题分开：价格是否比平时更安静，以及安静之后向哪边加速。","path":"learn/87-zh.html","title":"TTM Squeeze 波动挤压","g":"market","isDef":1},{"term":"Turtle Trading","name":"海龟交易法则","def":"海龟交易法则是一套规则化的趋势跟踪系统。","path":"learn/166-zh.html","title":"Turtle Trading 海龟交易法则","g":"market","isDef":1},{"term":"Ulcer Index","name":"溃疡指数","def":"Ulcer Index中文常叫溃疡指数，专门衡量价格跌离近期高点的压力。","path":"learn/88-zh.html","title":"Ulcer Index 溃疡指数","g":"market","isDef":1},{"term":"Ultimate Oscillator","name":"终极振荡器","def":"同时考虑短、中、长三个窗口的价格推动，减少只看一段长度的片面。","path":"learn/62-zh.html","title":"Ultimate Oscillator 终极振荡器","g":"market","isDef":1},{"term":"Valuation Multiples: P/E, P/B, and P/S","name":"估值指标：市盈率、市净率与市销率","def":"估值倍数是通过股价与特定财务基础指标对比衡量相对价格的指标体系。","path":"learn/185-zh.html","title":"Valuation Multiples: P/E, P/B, and P/S 估值指标：市盈率、市净率与市销率","g":"market","isDef":1},{"term":"Vertical Spreads","name":"垂直价差","def":"垂直价差（Vertical Spread）指针对同一标的资产、选择完全相同的到期日，同时买入 1 张某行权价的期权并卖出 1 张同类型（同为看涨或同为看跌）但不同行权价的期权。","path":"learn/213-zh.html","title":"Vertical Spreads 垂直价差","g":"market","isDef":1},{"term":"VIX","name":"波动率指数","def":"VIX常被媒体渲染为“恐慌指数”，但它并不是靠问卷调查出来的心理指标，而是用标普500指数期权（见本站「期权入门」一课）的真实真金白银报价算出来的未来30天预期波动幅度。","path":"info/learn/74-zh.html","title":"VIX 波动率指数","g":"info","isDef":1},{"term":"Volatility Smile & Skew","name":"波动率微笑与偏斜","def":"波动率微笑（Volatility Smile）与波动率偏斜（Volatility Skew，又称波动率歪笑 Smirk）指同一标的、同一到期日的不同行权价期权，其隐含波动率（IV）并非处于同一条水平线上：当深价内与深价外两侧行权价的 IV 均高于平值（ATM）期权、图形呈两端上翘的 U 型时称为“波动率微笑”；当某一侧（如股指期权中较低行权价的虚值看跌一侧）IV 显著高于另一侧、曲线呈单边倾斜时称为“波动率偏斜”。","path":"learn/211-zh.html","title":"Volatility Smile & Skew 波动率微笑与偏斜","g":"market","isDef":1},{"term":"Volatility Stop","name":"波动止损","def":"波动止损是一类退出方法：最近价格晃得大，留的缓冲通常更宽；晃得小，缓冲通常更窄。","path":"learn/92-zh.html","title":"Volatility Stop 波动止损","g":"market","isDef":1},{"term":"Volume","name":"成交量与均量线","def":"成交量记录一根K线内成交了多少股、币或合约；均量线是过去若干根的通常水平。","path":"learn/32-zh.html","title":"Volume 成交量与均量线","g":"market","isDef":1},{"term":"Volume and Price","name":"量价关系","def":"量价关系把每段走势分成四种组合：价涨量增、价涨量缩、价跌量增、价跌量缩。","path":"learn/157-zh.html","title":"Volume and Price 量价关系","g":"market","isDef":1},{"term":"Volume Delta","name":"成交量差值","def":"成交量差额Volume Delta比较一根K线里被归为正向和负向的成交量。","path":"learn/101-zh.html","title":"Volume Delta 成交量差值","g":"market","isDef":1},{"term":"Volume Footprint","name":"成交足迹图","def":"成交足迹图（Volume Footprint）把单根K线内部剖开，按价格格显示每一格的卖方成交量与买方成交量，帮你回答“这根K线内部哪个价位交手最密、哪边更主动”。","path":"learn/103-zh.html","title":"Volume Footprint 成交足迹图","g":"market","isDef":1},{"term":"Volume Profile","name":"成交量分布","def":"成交量分布（Volume Profile）把选定时间段的成交量按“价格高低”横向累加，帮你回答“过去这段时间大家最密集在哪个价位换手”。","path":"learn/99-zh.html","title":"Volume Profile 成交量分布","g":"market","isDef":1},{"term":"Vortex","name":"涡旋指标","def":"比较相邻 K 线之间向上与向下的移动哪一种更突出。","path":"learn/45-zh.html","title":"Vortex 涡旋指标","g":"market","isDef":1},{"term":"VWAP","name":"成交量加权均价","def":"VWAP从选定起点累计价格乘量，再除累计量，得到这段成交的加权平均参考。","path":"learn/37-zh.html","title":"VWAP 成交量加权均价","g":"market","isDef":1},{"term":"VWMA","name":"成交量加权均线","def":"VWMA把最近N根价格按成交量加权：成交越多的那根，对均价影响越大。","path":"learn/5-zh.html","title":"VWMA 成交量加权均线","g":"market","isDef":1},{"term":"Wallets & Exchange Custody","name":"钱包与交易所托管","def":"托管：资产放在交易所账户里，由交易所保管私钥，你用账号密码登录使用。","path":"learn/180-zh.html","title":"Wallets & Exchange Custody 钱包与交易所托管","g":"web3","isDef":1},{"term":"Wedges & Three Pushes","name":"楔形与三推","def":"三推：同一方向连续出现三个摆动高点（或低点），每一个都高于（低于）前一个，但每次推进的幅度逐次缩小。","path":"learn/133-zh.html","title":"Wedges & Three Pushes 楔形与三推","g":"market","isDef":1},{"term":"What a Stock Is","name":"股票是什么","def":"股票是公司所有权的一份凭证。","path":"learn/175-zh.html","title":"What a Stock Is 股票是什么","g":"market","isDef":1},{"term":"What Crypto Assets Are","name":"加密资产是什么","def":"加密资产是记录在区块链上的数字资产。","path":"learn/179-zh.html","title":"What Crypto Assets Are 加密资产是什么","g":"web3","isDef":1},{"term":"Williams %R","name":"威廉指标","def":"Williams %R也衡量收盘在近期高低区间的位置，只是用0到−100的倒向刻度：接近0靠顶部，接近−100靠底部。","path":"learn/14-zh.html","title":"Williams %R 威廉指标","g":"market","isDef":1},{"term":"Williams Alligator","name":"鳄鱼指标","def":"用三条快慢不同的平滑线，判断价格有没有从纠缠变成有序推进。","path":"learn/48-zh.html","title":"Williams Alligator 鳄鱼指标","g":"market","isDef":1},{"term":"Williams Fractals","name":"威廉分形","def":"威廉姆斯分形把一小组K线中的局部峰谷标出来。","path":"learn/97-zh.html","title":"Williams Fractals 威廉分形","g":"market","isDef":1},{"term":"WMA","name":"加权均线","def":"WMA把最近N根价格按轻重求平均，常见线性版本让最新一根权重最大，越旧越轻。","path":"learn/3-zh.html","title":"WMA 加权均线","g":"market","isDef":1},{"term":"Yield Aggregators & Restaking","name":"收益聚合与再质押","def":"收益聚合器是通过智能合约自动执行复利复投与跨协议调仓的链上资产管理工具；再质押则是将已质押的权益资产二次用于担保外部中间件或网络以获取叠加收益的机制。","path":"learn/225-zh.html","title":"Yield Aggregators & Restaking 收益聚合与再质押","g":"web3","isDef":1},{"term":"ZigZag","name":"之字转向","def":"ZigZag把零碎波动过滤掉，再用折线连接较大的转折，让你看清价格走过的大轮廓。","path":"learn/98-zh.html","title":"ZigZag 之字转向","g":"market","isDef":1}];
